def is_bounded(poly, b):
    """
    Check if the polynomial poly is bounded from below if b is filled in.
    """
    for a, b_prime in poly:
        if b_prime == 0 and b > 0:
            return False
        if b_prime > 0 and b == 0:
            return False
    return True

def game(chosen_scalar):
    total_coeffs = 0
    for a, b in poly:
        total_coeffs += a * b
    total_diff = chosen_scalar * total_coeffs
    if total_diff < 0:
        return 'Ani'
    for subpoly in combinations(poly, len(poly) - 1):
        if chosen_scalar == 0 and is_bounded(subpoly, 1):
            return 'Borna'
    return 'Ani' if chosen_scalar == 0 else 'Borna'

