def solve_problem(n, m, initial_state, final_state):
    operations = []

    for row in initial_state:
        index1 = 0
        while index1 < m:
            if row[index1:].startswith("1"):
                index2 = row.index("1")
                if index2 >= 1:
                    new_row = row[:index2] + row[index2 + 1:]
                    operations.append((1, index1 + 1, 1, index2 + 1))
                    index1 = index2 + 2  # skip empty cells
                else:
                    new_row = "0" + row[index1 + 1:]
                    operations.append((1, index1 + 1, 1, index1 + 1))
                    index1 = index1 + 2  # skip empty cells
            else:
                index1 = index1 + 1

    for row in final_state:
        index1 = 0
        while index1 < m:
            if row[index1:].startswith("0"):
                index2 = row.index("0") + 1
                if index2 <= m - 2:
                    new_row = "1" + row[:index2] + new_row[index2:]
                    operations.append((1, index1 + 1, 1, index2 - 1))
                    index1 = index2
                else:
                    new_row = final_state[-1] + row[1:]
                    operations.append((1, index1 + 1, len(final_state[-1]) + 1, 1))
                    index1 = index1 + 2  # skip empty cells
            else:
                index1 = index1 + 1

    return len(operations)

