import math
from typing import List

def compute_terminal_angle(a_i, d, x_i):
    start = min(x_i, a_i + d + 1)
    end = max(x_i, a_i)
    count = 1
    while start < end and a_i + 1 < end:
        mid = start + (end - start + 1) // 2
        differences = set()
        for i in range(a_i + 1, mid + 1):
            if i - a_i <= d:
                diff = i - mid
            else:
                diff = 2 * d + 1 - (i - a_i)
            differences.add(diff)
        end = mid + 1
        if len(differences) == 0:
            start = mid
        else:
            count += 1
            end = mid + 1
    return start, count * math.pi / (2 * len(differences))

def process_scene(n: int, d: int, a: List[int], m: int, x: List[int], results: List[float]):
    for i in range(m):
        results[i] = compute_terminal_angle(a[i], d, x[i])

