# Function to calculate AND results
def calculateResults(prims, clems):
    cache = [[] for _ in range(K)]
    mod = 998244353
    for i in range(M):
        mask = prims * ANDs[i][2]
        key = str(mask) + str(clems)
        if key not in cache[len(mask) - 1]: 
            dp = [0] * 2 ** len(mask)
            for j in range(len(mask)):
                dp[j] = ANDs[i][2] & mask
            for j in range(2 ** len(mask)):
                for p in range(2 ** len(mask)):
                    for q in range(2 * len(mask)):
                        if bitwiseOr(dp[j], p) == bitwiseOr(q, mask):
                            dp[j] += comb(j, p) * comb(len(mask) - 1 - p, q - len(mask)) % mod
            cache[len(mask) - 1].append((mask, dp))
    return cache[-1][0][0], reduce(mul, [c[len(mask)] for c in cache], mod)**combinations[len(mask)] % mod % mod

def bitwiseOr(a, b):
