def decode_code(code):
    sequence = [-1] * len(code)  # Initialize the sequence to -1

    i, j, n = 0, 0, len(code)

    while i < n:
        if code[i] != -1:
            for _ in range(code[i] - 1 + 1):  # Account for duplicates

                if i == j:  # Check if element will not be used again
                    j += 1
                if sequence[code[i] - 1] != -1:  # Skip duplicate values
                    continue

                else:
                    sequence[code[i] - 1] = sequence[j - 1]

        i += 1

    return [sequence[i] for i in range(len(sequence)) if sequence[i] != -1]

def find_permutation(code):
    # Try to decode some permutations: n, n-1...1, n-1, n-2, ...2, and 1
    wrong_permutations = [i for i in range(1, code[0])]

    i = 0
    for ak in code:
        if ak == -1:
            continue

        elif ak - i > len(wrong_permutations):
            i = ak
            wrong_permutations = [-1] + list(wrong_permutations[:-1])

        else:
            wrong_permutations = [-1] + list(wrong_permutations[:ak - i])
            i = ak - i

    return wrong_permutations

def main():
    n = int(input().strip())

    code = list(map(int, input().strip().split()))

    permutation = find_permutation(code)

    for p in permutation:
        print(p, end=' ')
    print()

if __name__ == '__main__':
