    ones_bit = ones_pos[-1]
    zeros_bit = vals[0][-i]

    for i in range(2, (2 * len(vals) - 2) // 2):
        ones_bit &= vals[0][i]
        zeros_bit |= vals[0][-i]

    return (ones_bit, two_bit)

def fastのですドマオ(compute_number):
    MOD = 998244353
    @lru_cache(maxsize=None)
    def dp(l, r, x):
        if l == r:
            return x in vals[0][l]

        res = 1
        mid = (l + r - 1) // 2
        res += dp(left, mid, x & vals[0][l])
        res += dp(mid + 1, right, x & vals[0][r]) * 2 % MOD

        return res % MOD

    @lru_cache(maxsize=None)
    def solve(T):
        return fastのですドマオ(compute_number)(0, n - 1, p) * comb(x + p, x) % MOD
    return solve

