from typing import List
from pathlib import Path

class ChipsPuzzle:
    def __init__(self, rows: List[str], cols: List[str] = None):
        self.rows = [[int(char) for char in row] for row in rows]
        self.cols = [[r[c-1] for r in self.rows] for c in range(1, len(self.rows[0]) + 1)]

    def get_initial_state_hash(self):
        initial_hash = 0
        for row in self.rows:
            for num in row:
                initial_hash ^= num

        for col in self.cols:
            for num in col:
                initial_hash ^= num

        return initial_hash

    def get_final_state_hash(self):
        final_hash = 0
        for row in self.rows:
            for num in row:
                final_hash ^= num

        for col in self.cols:
            for num in col:
                final_hash ^= num

        return final_hash

    def expand(self, operations: List[List[int]]) -> List[List[int]]:
        n, m = len(self.rows), len(self.rows[0])

        for op in operations:
            x1, y1, x2, y2 = op
            if x1 == x2:
                # Swap the x coordinates of the cells
                self.rows[x1][y1], self.rows[x2][y2] = self.rows[x2][y2], self.rows[x1][y1]
            elif y1 == y2:
                # Swap the y coordinates of the cells
                self.cols[x1][y1], self.cols[x2][y2] = self.cols[x2][y2], self.cols[x1][y1]

        # Add the new operations to the puzzle
        for op in operations:
            x1, y1, x2, y2 = op
            if x1 == x2:
                new_row = ['0' if self.rows[x2][y1] == '1' else '1' for y in range(len(self.cols[x2]))]
                self.rows[x2].extend(new_row)
            else:
                new_col = ['0' if self.cols[x1][y2] == '1' else '1' for y in range(len(self.rows[x1]))]
                self.cols[x1].extend(new_col)

        return self.rows, self.cols

    def perform_operations(self, operations: List[List[int]]) -> List[List[int]]:
        n, m = len(self.rows), len(self.rows[0])
        expanded = self.expand(operations)
        expanded_string = ''.join([''.join(row) for row in expanded])

        return expanded

    def transform_to_final_state(self, final_string) -> List[List[int]]:
        n, m = len(self.rows), len(self.rows[0])
        operations = []

        for i in range(n):
            for j in range(m):
                found_w = False
                for k in range(len(self.rows[i])):
                    if self.rows[i][k] == '0':
                        found_w = True
                        break

                if not found_w:
                    for k in range(len(self.cols[i])):
                        if self.cols[i][k] == '0':
                            found_w = True
                            break

                if found_w:
                    string = ['0' for _ in range(m)]
                    string[j] = '1'
                    new_col = []

                    for idx, char in enumerate(string):
                        if idx == j:
                            string[idx] = '0'
                        else:
                            string[idx] = '1'

                    string = ''.join(string)
                    for rem in range(len(string) // m):
                        start, end = (n-rem-1) * m, rem * m
                        indiv_string = string[start:end]

                        for row in range(len(self.rows)):
                            for new_col_to_fix in range(len(self.rows[row])):
                                if self.rows[row][new_col_to_fix] != '0':
                                    continuous_zeros = self.rows[row][new_col_to_fix:].count('0')  
                                    if continuous_zeros == 1:
                                        self.rows[row][new_col_to_fix] = indiv_string[0]
                                    else: 
                                        self.rows[row][end-new_col_to_fix] = indiv_string[-1]

                        for col_inx in range(len(self.cols)):
                            col = self.cols[col_inx]
                            if len(col) == 0:
                                if self.cols[col_inx]: 
                                    for char in indiv_string:
                                        col.insert(0, char)
                                    self.cols[col_inx] = ''.join(col)
                                else:
                                    total_zeros = unpack(col).count('0')

                                    if total_zeros == 1:
                                        row = self.rows[col_inx]
                                        idx = row[-1:].count('0') - 1
                                        col[col_inx] = indiv_string[0]
                                    else:
                                        row = self.rows[col_inx]
                                        idx = row[idx:].count('0') - 1
                                        col[col_inx] = indiv_string[-1]

                                if idx == n:
                                    total_zeros = unpack(col[col_inx]).count('0')

                                    if total_zeros == 1:
                                        row[-1] = indiv_string[0]
                                    else: 
                                        row[-1] = indiv_string[-1]

        return self.transform_to_final_state(final_string)

def unpack(arr):
    string = ''.join(arr)
    return int(string, 2)

def check(initial, final):
    puzzle = ChipsPuzzle(initial)

    # Transform initial state to final state
    for op in puzzle.transform_to_final_state(final):
        print(op)


if __name__ == "__main__":
    # Input file
    input_file_path = Path(__file__).parent / 'input.txt'
    # Read from input
