def is_valid(n: int, rem: List[int], m: int) -> bool:
    # Calculate total points if tournament results were known
    total_points = sum(2 * (i < m) + (m - i) for i in range(m))

    if total_points < sum(2 * (i < m) + (m - i) for i in rem):
        return False

    past = set()

    def dfs(used: List[bool], pos: int) -> bool:
        if pos == m:
            return any(2 * (i < m) + (m - i) == rem_pos for rem_pos in rem)

        for i in range(m):
            if not used[i] and (i == m - 1 or used[i - 1]):
                used[i] = True
                rem_pos = rem[i]
                if dfs(used, pos + 1):
                    return True
                used[i] = False
                rem[pos] = rem[rem_pos]
        return False

    return dfs([False] * m, 0)

def generate_tournament(n: int, rem: List[int], m: int, out: List[List[str]]) -> bool:
