from math import comb
from functools import lru_cache

def count_arrays(n, k, m, conditions):
    mod = 998244353

    @lru_cache(None)
    def dp(i, mask, used):
        if i == n:
            return 1
        results = 0

        for j in range(n):
            if used & (1 << j):
                results += dp(j + 1, mask & ((1 << k) - 1), used ^ (1 << j))

        # Adjust result based on condition
        if used & ((1 << k) - 1):
            return results
        results *= comb(used, used ^ (1 << k)) // 2

        # If the bitwise AND is exactly what was asked for
        if used & x[i]:
            results *= 2
            if used & y[i]:
                results += 8  # All numbers that can fulfill this condition
        else:
            return results

        return results % mod

    x = [0] * m  # Required bitwise AND values for each condition segment
    y = [0] * m  # Oracles: for each condition segment, can N numbers from L to R have bitwise AND value x?

    for i in range(m):
        l, r, xor_val = map(int, conditions[i])
        x[i] = xor_val
        y[i] = 1 if xor_val in range(2**k) else 0

    return dp(0, (1 << k) - 1, (1 << k) - 1) % mod

print(count_arrays(4, 3, 2, [[1, 3, 3], [3, 4, 6]]))
