import sys

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def largest_divisor():
    m, l, r, k = map(int, input().split())
    ans = l

    for i in range(k-1):
        diff = r - l
        if diff % k == 0:
            d = diff // k
        else:
            d = diff // k + 1
        div = d - l
        while div <= ans:
            while ans % div != 0:
                div += k
            div = div // gcd(div, d)
        ans = ans // gcd(ans, d)
        if ans == 1:
            return 0

        diff -= d
        if not diff:
            break
        ans += diff 
        l = l + d

    return ans % m

