from typing import List

def find_stable_pairing(n: int, costs: List[List[int]]) -> List[int]:
    """
    Finds a stable pairing of cities so that the cost of building a train line between each pair does not increase if a city is paired with a different city.

    :param n: Number of cities.
    :param costs: A list of N-1 pairings between the cities.
    :return: A list of N integers where O_i is the city to which city i should be paired, or -1 if no stable pairing exists.
    """
    costs.append([-1] * n)  # Append sentinel value for adjacent costs
    for i in range(n):
        costs[i].append(costs[i][-1])  # Reflect costs to help finding cycles

    def can_pair(city: int, candidate: int) -> bool:
        # If the swapping costs the same, pair can't be chosen
        if candidate - 1 == city:
            return False
        # If both values are the same, cannot be paired
        if costs[city][city] == 0 and costs[candidate][candidate] == 0:
            return False
        # Check if swapping city with candidate isn't in costs list
        for i in range(len(costs)):
            if i != city and i != candidate and costs[city] is not None and costs[candidate] is not None:
                if costs[i][city] == costs[candidate][i]:
                    return False
        return True

    # Try every possible pairings
    for i in range(n):
        costs[i][i] = costs[i + 1][i] = float('inf')  # Reset values for pairings
        for j in range(n):
            if costs[i][j] == float('-inf'):
                continue
            for k in range(n):
                if not can_pair(city=i, candidate=k):
                    break
            else:
                break
        else:
            return [i + 1] + [w[i] for w in costs[n:]] + [k + 1 for k in range(n) if k != i] + [j + 1] 
    return [-1] 

# Example usage
