import math

def calculate_effetive_resistance(resistances):
    result = 0
    for resistance in resistances:
        result += resistance
    return result

def solve(circuit):
    resistances = []
    total_resistance = 0
    previous_resistance = 0

    i = 0
    while i < len(circuit):
        if circuit[i] == '*':
            if i < len(circuit) - 1 and circuit[i+1] != '*':
                j = i + 1
                while circuit[j] != '*':
                    j += 1
                total_resistance += calculate_effetive_resistance(resistances) - previous_resistance
                resistances = []
                i = j
            else:
                resistances.append(1)
                i += 1
        else:
            resistances.append(calculate_effetive_resistance(resistances) - previous_resistance)
            total_resistance += resistances[-1]
            previous_resistance = resistances[-1]
            i += 1

    if len(resistances) == 0:
        return "REVOLTING"
    elif total_resistance != calculate_effetive_resistance(resistances):
        return "REVOLTING"

    return "REVOLTING " + " ".join(map(str, resistances))

def main():
    t = int(input())
    for _ in range(t):
        r = int(input())
        circuit = input()[1:-1]
        print(solve(circuit))

if __name__ == "__main__":
    main()
