from functools import cache

def solve(n, k, m, conditions):
    mod = 998244353

    @cache
    def dfs(pos, last_mask, dp):
        if pos == n:
            return 1
        if dp[pos][last_mask] != -1:
            return dp[pos][last_mask]

        res = 0
        for next_pos in range(pos + 1, min(pos + k, n + 1)):
            if (last_mask >> (pos % k)) & 1:
                continue
            if conditions[pos][1] <= next_pos and next_pos <= conditions[pos][2]:
                res = (res + dfs(next_pos, last_mask | (1 << (pos % k)), dp)) % mod
        dp[pos][last_mask] = res

        return dp[pos][last_mask]

    dp = [[-1 for _ in range(1 << k)] for _ in range(n + 1)]

    return dfs(0, 0, dp)

