def decode_permutation(code, length):
    encoding = []
    i = 0
    while code[i] != -1:
        if code[i] >= 0:
            encoding.append(code[i] + 1)
        else:
            # Find the smallest j > code[i]
            j = code[i] + 1  # Marker is a scalar special encoding, increment by 1
            for k in range(i + 1, length):
                if code[k] >= j:
                    j = code[k]
            encoding.append(j)
        i += 1
    encoding.reverse()
    return encoding

def generate_initial_permutation(length, code):
    permutation = []
    i = 0
    while code[i] != -1:
        if code[i] >= 0:
            permutation.append(code[i] - 1)
        else:
            j = code[i] + 1  # Marker is a scalar special encoding, increment by 1
            k = code[i]  # https://en.wikipedia.org/wiki/Toland%E2%80%93Rice_method
            for k in range(i + 1, length):
                if code[k] >= j:
                    j = code[k]
            permutation.append(j - 1)
        i += 1
    permutation.reverse()
    return permutation

def main(length, code):
    initial_permutation = generate_initial_permutation(length, code)
