def find_best_city_to_pair(N, costs):
    pairs = range(N)
    min_cost = inf
    for i in pairs:
        for j in pairs:
            if i < j:
                # Checking if it's possible to pair i with j
                if costs[i][j] + costs[j][i] < min_cost:
                    min_cost = costs[i][j] + costs[j][i]
                    best_cities = [i, j]
            elif i > j:
                # Checking if it's possible to pair i with j with a reverse connection
                if costs[i][j] + costs[i][i] < min_cost:
                    min_cost = costs[i][j] + costs[i][i]
                    best_cities = [i, j]
    # Finding the cost difference
    last_cities = [0, 1] if best_cities == [0, 1] else [1, 0]
    detechment_cost = min_cost + costs[last_cities[0]][last_cities[1]]
