def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    else:
        g, x, y = extended_gcd(b, a % b)
        return g, y, x - y * (a // b)

class FastModInverse:
    def __init__(self, mod_val):
        self.mod_val = mod_val
        n, d, k = extended_gcd(self.mod_val, 998244353)
        self.g = n * pow(d, 998244353 // 4, 998244353)
        self.inv = (pow(mod_val, -1, 998244353) * d) % 998244353

    def __call__(self, a):
        return a * self.g % self.mod_val * self.inv % self.mod_val

def ncr(n, r, M):
    mod_val = M if M <= 50000 else 998244353
    if n - r < r:
        r = n - r

    res = 1
    for i in range(r):
        res *= (n - i) % mod_val
        res %= mod_val

    res *= FastModInverse(mod_val).nInverse(n) % mod_val
    res *= FastModInverse(mod_val).nInverse(r) % mod_val
    res *= FastModInverse(mod_val).nInverse(n - r) % mod_val
    return res % mod_val

def c(n, m):
    return ncr(n, m, 998244353)

def solve(n, k, conditions):
    mod_val = 998244353
    dp = [0] * k
    for l, r, x in conditions:
        if l % 2 != r % 2:
            return 0

        margin = 1 << (l % 2)
        for i in range(l // 2, r + 1):
            if i > k:
                continue
            x_l = dp[i - 1]
            mi = max(0, x - c(k, i) * dp[i] % mod_val)
            for j in range(i + 1, l // 2 + 1):
                mi = max(mi, c(k, j) * dp[j] % mod_val)
            remaining = margin - (x - mi)
            for j in range(r // 2 + 1, min(l % 2 + 1, j + 1)):
                remaining -= c(k, j) * dp[j] % mod_val
            if remaining >= 0:
                dp[i - 1] += remaining % mod_val
                dp[i - 1] %= mod_val

        for i in range(l // 2 + 1, min(r // 2 + 1, l % 2 + 1)):
            mi = max(0, x - c(k, i) * dp[i] % mod_val)
            dp[i - 1] -= mi % mod_val
            dp[i - 1] %= mod_val

            x_l = dp[i - 1]

    res = 0
    return res + dp[-1] if l % 2 != r % 2 else res + dp[-1] % mod_val

n, k, m = map(int, input().split())
conditions = []
mod_val = pow(2, k, 998244353)
for _ in range(m):
    l, r, x = map(int, input().split())
    conditions.append((l - 1, r, x))
print(solve(n, k, conditions))
