def decode_code(code, reverse=False):
    N = len(code)
    stack = [0]
    binary_code = ['0'] * N
    for i, v in enumerate(code):
        if v == -1:
            stack.append(-1)
            binary_code[i] = '0'
        elif  v > 0:
            stack.append(v)
            binary_code[stack[i+1]] = '1'

    # restore code to include digit flips
    mod_3_value = '2'
    prev_digit = 0
    for i, e in enumerate (code):
        if e == -1:
            prev_digit = 0
            coded_value = mod_3_value
        elif e > 0:
            coded_value = str(e)
        else:
            prev_digit = 0
            continue

        for j, bit in enumerate(binary_code):
            if bit == coded_value[-1-j]:
                break
            if j == len(coded_value) -1:
                prev_digit = 1
            else:
                prev_digit = 0

        binary_code[i] = coded_value + mod_3_value if prev_digit == 1 else coded_value
        mod_3_value = '1' if mod_3_value == '2' else '0'

    return ''.join(binary_code)

