from math import comb

def is_possible(num_points, n):
    m = len(num_points)
    num_players = sorted([(int((m*(m-1)-i*(i-1))/2)-sum(num_points[:i])) for i in range(1, m+1)])
    if num_points + [0] == num_players[:n]:
        return True
    if num_players == [0] * (m*n) + [m] * n:
        return True
    if 0 not in num_players[:n] and sum(num_players[:n]) == (comb(m, 2) + (m if n == m else 0)):
        return True
    return False

def generate_tournament(tournament, index):
    if index == m:
        print(" ".join(tournament))
        if is_possible(tournament, n):
            return True
        return False
    for i in range(m):
        if tournament[i] != 'X' and tournament[max_index(i, index)] != 'X':
            tournament[index] = 'W' if index > max_index(i, index) else 'L'
            tournament[i] = 'W' if index < max_index(i, index) else 'L'
            if generate_tournament(tournament, index+1):
                return True
            tournament[index] = 'X'
            tournament[i] = 'X'
    return False

def max_index(i, j):
    if i > j:
        return j
    else:
        return i

tournament = ['X'] + ['L'] * m + ['X']
generate_tournament(tournament, 0)
