import sys

MOD = 998244353

def mod_pow(a, n, mod):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * a) % mod
        a = (a * a) % mod
        n = n // 2
    return result

def count_arrays(n, k, m, conditions):
    dp = {}
    dp[0] = 1

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] * 2 % MOD

        for j in range(m):
            l, r, x = conditions[j]
            if i >= r:
                dp[i] -= dp[i - l - 1] * mod_pow(2, k - j, MOD) % MOD

            if i >= l and i < r:
                dp[i] -= dp[i - l] * mod_pow(x, k - j - 1, MOD) % MOD

            if i >= l and i == r:
                dp[i] += dp[i - l - 1] * mod_pow(x, k - j, MOD) % MOD

        dp[i] %= MOD

    return dp[n]

