def find_permutation(code):
    permutation = []
    used = [False] * (len(code) + 1)
    max_idx = len(code)

    for i in range(len(code)):
        min_idx = i

        for j in range(i + 1, len(code) + 1):
            if code[j] != -1 and not used[code[j]]:
                if code[j] != max_idx:
                    min_idx = j
                used[code[j]] = True

        permutation.append(max_idx)
        if min_idx != i:
            permutation.append(min_idx)
        max_idx = code[min_idx] if min_idx != i else len(code)

    return tuple(permutation)

