def min_sets(colors):
    import math

    # Count the frequency of each color
    color_counts = {}
    for color in colors:
        if color in color_counts:
            color_counts[color] += 1
        else:
            color_counts[color] = 1

    total_sets = 0

    # Each color needs at least one set
    for count in color_counts.values():
        total_sets += math.ceil(count / 2)

    # If total count of balls is odd, there must be an odd color which requires an extra set
    if total_sets * 2 < math.ceil(sum(colors) / 2):
        total_sets += 1

    return total_sets
